//! The index-string oracle: this crate's encoder versus upstream's own output.
//!
//! `testdata/vectors/index-strings.json` records, for every index of every upstream
//! fixture schema, the exact string upstream's `getIndexableStringMonad` produces
//! (900 cases), the exact bound strings
//! `getStartIndexStringFromLowerBound`/`FromUpperBound` produce (406 of those), and
//! the declared length `getIndexStringLength` produces (89). It is generated by
//! running upstream RxDB at pin `3b763ee17` in Node, not by our Rust.
//!
//! The schemas come from `testdata/vectors/schema-hashes.json`, which records
//! upstream's *defaulted* schemas — so these tests feed the encoder the same input
//! upstream saw, including the `_deleted`-prefixed and `_meta.lwt` indexes that
//! `fillWithDefaultSettings` injects.
//!
//! This test is why `dxdb-memory`'s local index-string implementation is defensible
//! while `dxdb-query` is unpublished: the duplicate cannot drift from upstream
//! without this failing. When lane B publishes, the encoder is replaced and this
//! test moves with it.
//!
//! The `kind: "bounds"` cases are the important ones. They probe values at, inside
//! and beyond each schema's declared `minimum`/`maximum`, which is where the
//! clamping rule lives and where a reimplementation goes silently wrong: an
//! unclamped bound string is a different *length* than a real one, so a range query
//! does not merely mis-order results, it stops matching documents at all.

use std::collections::BTreeMap;

use dxdb_memory::index_strings::{
    get_index_string_length, get_indexable_string, get_start_index_string_from_lower_bound,
    get_start_index_string_from_upper_bound, index_max_str, BoundValue,
};
use serde::Deserialize;
use serde_json::Value;

#[derive(Debug, Deserialize)]
struct IndexStrings {
    #[serde(rename = "caseCount")]
    case_count: usize,
    cases: Vec<IndexCase>,
    /// The schemas upstream *refused*, with the error it raised. Asserted here so a
    /// port that accepts them is caught.
    #[serde(default)]
    rejections: Vec<Rejection>,
}

#[derive(Debug)]
struct IndexCase {
    schema: String,
    index: Vec<Value>,
    kind: String,
    why: String,
    document: Option<Value>,
    index_string: Option<String>,
    /// Which index field this probe moves; the others stay at their neutral filler.
    field: Option<String>,
    /// The probe value, three ways. Absent means the generator probed JavaScript
    /// `undefined` (JSON cannot carry `undefined`, so the key is dropped); an
    /// explicit `null` means it probed `null`. Those are *different* upstream
    /// branches, and flattening both into `Option<Value>` silently conflates them —
    /// which is exactly the bug this tri-state exists to prevent.
    probe: Probe,
    /// The probe value as JSON, for diagnostics.
    probe_json: Option<Value>,
    lower_bound_string: Option<String>,
    upper_bound_string: Option<String>,
    length: Option<usize>,
}

/// An input upstream refused, and the class of refusal.
#[derive(Debug, Deserialize)]
struct Rejection {
    schema: String,
    index: Vec<Value>,
    /// The rule upstream enforced, e.g. `upstream-requires-numeric-index-bounds`.
    /// Asserted loosely (one of the known classes) so a new class is noticed rather
    /// than silently absorbed.
    class: String,
    /// RxDB error code when upstream raised an `RxError`; `null` for a `TypeError`.
    #[serde(rename = "errorCode", default)]
    error_code: Option<String>,
}


/// The three shapes a `bound` probe can have in the vector file.
#[derive(Clone, Copy, Debug, PartialEq)]
enum Probe {
    /// The `bound` key was absent: the generator probed JavaScript `undefined`.
    Undefined,
    /// `"bound": null`: the generator probed `null`, which takes a different branch.
    Null,
    /// A concrete JSON value.
    Value,
}

impl<'de> serde::Deserialize<'de> for IndexCase {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        // Deserialize into a map first so "the key is absent" is observable. A
        // derived struct cannot tell `some_option: None` from "key missing", and
        // that distinction is the whole point here.
        let raw = serde_json::Map::deserialize(deserializer)?;
        let get_str = |key: &str| raw.get(key).and_then(Value::as_str).map(str::to_string);
        let probe = match raw.get("bound") {
            None => Probe::Undefined,
            Some(Value::Null) => Probe::Null,
            Some(_) => Probe::Value,
        };
        Ok(IndexCase {
            schema: get_str("schema").ok_or_else(|| serde::de::Error::missing_field("schema"))?,
            index: raw
                .get("index")
                .and_then(Value::as_array)
                .cloned()
                .ok_or_else(|| serde::de::Error::missing_field("index"))?,
            kind: get_str("kind").unwrap_or_default(),
            why: get_str("why").unwrap_or_default(),
            field: get_str("field"),
            document: raw.get("document").cloned(),
            index_string: get_str("indexString"),
            probe,
            probe_json: raw.get("bound").cloned(),
            lower_bound_string: get_str("lowerBoundString"),
            upper_bound_string: get_str("upperBoundString"),
            length: raw.get("length").and_then(Value::as_u64).map(|n| n as usize),
        })
    }
}

#[derive(Debug, Deserialize)]
struct SchemaHashes {
    cases: Vec<SchemaHashCase>,
}

#[derive(Debug, Deserialize)]
struct SchemaHashCase {
    name: String,
    #[serde(rename = "defaultedSchema")]
    defaulted_schema: Value,
}

fn read_vector(name: &str) -> String {
    let path = format!("{}/../../../testdata/vectors/{name}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("read {path}: {error}; run `make vectors` at the repo root"))
}

fn load() -> (IndexStrings, BTreeMap<String, Value>) {
    let index_strings: IndexStrings =
        serde_json::from_str(&read_vector("index-strings.json")).expect("parse index-strings");
    let hashes: SchemaHashes =
        serde_json::from_str(&read_vector("schema-hashes.json")).expect("parse schema-hashes");
    let schemas = hashes
        .cases
        .into_iter()
        .map(|case| (case.name, case.defaulted_schema))
        .collect();
    (index_strings, schemas)
}

/// An index from the vector is a list of field paths. A literal number in an index
/// is the `CI1` case upstream refuses, so it is surfaced as an error here too
/// rather than being stringified.
fn index_paths(raw: &[Value]) -> Result<Vec<String>, String> {
    raw.iter()
        .map(|segment| match segment {
            Value::String(field) => Ok(field.clone()),
            other => Err(format!(
                "index contains the literal {other}, not a field path"
            )),
        })
        .collect()
}


/// Reconstructs the positional bound vector a `kind: "bounds"` case was produced
/// from: `field` carries the probe value, every other position carries the neutral
/// filler the generator used.
///
/// The filler rule (`index-strings.mjs` `neutral`): a numeric field is held at its
/// declared `minimum` (or 0 when it has none), a boolean at `false`, a string at
/// `""`. Getting this wrong does not produce a slightly different string — it
/// produces one of a different length, which is why these cases are worth porting
/// exactly.
fn neutral_bounds(
    schema: &Value,
    index: &[String],
    probed_field: &str,
    probe: Probe,
    probe_json: Option<&Value>,
) -> Result<Vec<BoundValue>, String> {
    let mut bounds = Vec::with_capacity(index.len());
    let mut saw_probed_field = false;
    for path in index {
        let part = dxdb_memory::index_strings::get_schema_by_object_path(schema, path)
            .ok_or_else(|| format!("index field '{path}' is not in properties"))?;
        let field_type = part.get("type").and_then(Value::as_str).unwrap_or("string");
        if path == probed_field {
            saw_probed_field = true;
            // `undefined` is recorded as an absent `bound` member; an explicit
            // `"bound": null` is the *null* probe. They are different upstream
            // branches, so they must stay different here.
            bounds.push(match probe {
                Probe::Undefined => BoundValue::Undefined,
                Probe::Null => BoundValue::Null,
                Probe::Value => BoundValue::from_json(
                    probe_json.expect("a value probe carries its value"),
                ),
            });
            continue;
        }
        bounds.push(match field_type {
            "number" | "integer" => BoundValue::Value(Value::from(
                part.get("minimum").and_then(Value::as_f64).unwrap_or(0.0),
            )),
            "boolean" => BoundValue::Value(Value::Bool(false)),
            _ => BoundValue::Value(Value::String(String::new())),
        });
    }
    if !saw_probed_field {
        return Err(format!(
            "probed field '{probed_field}' is not one of the index fields [{}]",
            index.join(",")
        ));
    }
    Ok(bounds)
}

/// Every `kind: "index-string"` case: a document and the exact string upstream
/// encodes it to.
#[test]
fn index_strings_match_upstream() {
    let (vectors, schemas) = load();
    let mut checked = 0usize;
    let mut failures = Vec::new();

    for case in vectors.cases.iter().filter(|case| case.kind == "index-string") {
        let Some(document) = &case.document else {
            continue;
        };
        let Some(expected) = &case.index_string else {
            continue;
        };
        let schema = schemas
            .get(&case.schema)
            .unwrap_or_else(|| panic!("vector names schema '{}' which is not in the hash vector", case.schema));
        let index = match index_paths(&case.index) {
            Ok(index) => index,
            Err(reason) => {
                failures.push(format!(
                    "{}/{} [{}]: {reason}",
                    case.schema, case.why, case.kind
                ));
                continue;
            }
        };
        match get_indexable_string(schema, &index, document) {
            Ok(actual) if &actual == expected => checked += 1,
            Ok(actual) => failures.push(format!(
                "{} [{}] index [{}]:\n  expected {expected:?}\n  actual   {actual:?}",
                case.schema,
                case.why,
                index.join(",")
            )),
            Err(error) => failures.push(format!(
                "{} [{}] index [{}]: encoder refused: {error}",
                case.schema,
                case.why,
                index.join(",")
            )),
        }
    }

    assert!(checked > 300, "expected hundreds of index-string cases, checked {checked}");
    assert!(
        failures.is_empty(),
        "{} of {} index-string cases disagree with upstream:\n{}",
        failures.len(),
        checked + failures.len(),
        failures.join("\n\n")
    );
}

/// Every `kind: "bounds"` case: both bound strings for one probe value.
#[test]
fn bound_strings_match_upstream() {
    let (vectors, schemas) = load();
    let mut checked = 0usize;
    let mut failures = Vec::new();

    for case in vectors.cases.iter().filter(|case| case.kind == "bounds") {
        let schema = schemas
            .get(&case.schema)
            .unwrap_or_else(|| panic!("vector names schema '{}'", case.schema));
        let index = match index_paths(&case.index) {
            Ok(index) => index,
            Err(reason) => {
                failures.push(format!("{}/{}: {reason}", case.schema, case.why));
                continue;
            }
        };
        // Bounds are **positional**: one entry per index field. The generator probes
        // one field at a time and holds the rest at a neutral filler — the field's
        // declared minimum for numbers, `false` for booleans, `""` for strings —
        // which is why the case records `field` and `bound` rather than a whole
        // bound vector. Reconstruct that here. (`xtask/vectors/families/index-strings.mjs`
        // `neutral` + the positional loop.)
        let Some(field) = case.field.as_deref() else {
            failures.push(format!("{} [{}]: bounds case names no field", case.schema, case.why));
            continue;
        };
        let bounds = match neutral_bounds(schema, &index, field, case.probe, case.probe_json.as_ref()) {
            Ok(bounds) => bounds,
            Err(reason) => {
                failures.push(format!("{} [{}]: {reason}", case.schema, case.why));
                continue;
            }
        };

        if let Some(expected) = &case.lower_bound_string {
            match get_start_index_string_from_lower_bound(schema, &index, &bounds) {
                Ok(actual) if &actual == expected => checked += 1,
                Ok(actual) => failures.push(format!(
                    "{} [{}] lower bound of [{}]:\n  expected {expected:?}\n  actual   {actual:?}",
                    case.schema,
                    case.why,
                    index.join(",")
                )),
                Err(error) => failures.push(format!(
                    "{} [{}] lower bound refused: {error}",
                    case.schema, case.why
                )),
            }
        }
        if let Some(expected) = &case.upper_bound_string {
            match get_start_index_string_from_upper_bound(schema, &index, &bounds) {
                Ok(actual) if &actual == expected => checked += 1,
                Ok(actual) => failures.push(format!(
                    "{} [{}] upper bound of [{}]:\n  expected {expected:?}\n  actual   {actual:?}",
                    case.schema,
                    case.why,
                    index.join(",")
                )),
                Err(error) => failures.push(format!(
                    "{} [{}] upper bound refused: {error}",
                    case.schema, case.why
                )),
            }
        }
    }

    assert!(checked > 400, "expected hundreds of bound cases, checked {checked}");
    assert!(
        failures.is_empty(),
        "{} of {} bound cases disagree with upstream:\n{}",
        failures.len(),
        checked + failures.len(),
        failures.join("\n\n")
    );
}

/// Every `kind: "index-string-length"` case.
#[test]
fn index_string_lengths_match_upstream() {
    let (vectors, schemas) = load();
    let mut checked = 0usize;
    let mut failures = Vec::new();

    for case in vectors
        .cases
        .iter()
        .filter(|case| case.kind == "index-string-length")
    {
        let Some(expected) = case.length else {
            continue;
        };
        let schema = schemas
            .get(&case.schema)
            .unwrap_or_else(|| panic!("vector names schema '{}'", case.schema));
        let index = match index_paths(&case.index) {
            Ok(index) => index,
            Err(reason) => {
                failures.push(format!("{}/{reason}", case.schema));
                continue;
            }
        };
        match get_index_string_length(schema, &index) {
            Ok(actual) if actual == expected => checked += 1,
            Ok(actual) => failures.push(format!(
                "{} index [{}]: expected length {expected}, got {actual}",
                case.schema,
                index.join(",")
            )),
            Err(error) => failures.push(format!(
                "{} index [{}]: length refused: {error}",
                case.schema,
                index.join(",")
            )),
        }
    }

    assert!(checked > 80, "expected dozens of length cases, checked {checked}");
    assert!(
        failures.is_empty(),
        "{} of {} length cases disagree with upstream:\n{}",
        failures.len(),
        checked + failures.len(),
        failures.join("\n\n")
    );
}

/// The four schemas/indexes upstream refuses must be refused here too.
///
/// This is the assertion that the port has not become *more permissive*: silently
/// accepting an index with a literal number, a numeric field with no bounds, or a
/// field that does not exist produces index strings that sort wrongly, which is
/// worse than refusing to open the schema.
#[test]
fn inputs_upstream_rejects_are_rejected_here() {
    let (vectors, schemas) = load();
    assert!(
        vectors.rejections.len() >= 4,
        "expected at least the four refused inputs, found {}",
        vectors.rejections.len()
    );

    const KNOWN_CLASSES: [&str; 3] = [
        "upstream-rejects-non-string-index-entry",
        "upstream-requires-numeric-index-bounds",
        "upstream-rejects-missing-indexed-field",
    ];

    for case in &vectors.rejections {
        assert!(
            KNOWN_CLASSES.contains(&case.class.as_str()),
            "unhandled rejection class '{}' for {} {:?}; the port must classify it",
            case.class,
            case.schema,
            case.index
        );
        let schema = schemas
            .get(&case.schema)
            .unwrap_or_else(|| panic!("rejection names schema '{}'", case.schema));

        // A literal number in the index is refused before any schema work.
        let index = match index_paths(&case.index) {
            Ok(index) => index,
            Err(_reason) => {
                // `upstream-rejects-non-string-index-entry`: the refusal is the
                // index's shape, which `index_paths` already performed.
                assert_eq!(case.class, "upstream-rejects-non-string-index-entry");
                continue;
            }
        };

        let document = serde_json::json!({});
        let encoded = get_indexable_string(schema, &index, &document);
        assert!(
            encoded.is_err(),
            "{} index [{}] must be refused ({}); got {:?}",
            case.schema,
            index.join(","),
            case.class,
            encoded
        );

        // The reason must match the class, not merely be *some* error: a port that
        // rejects every index would otherwise pass this test.
        //
        // The RxDB error code is part of the recorded evidence: `CI1` is the
        // documented "index names a field that does not exist" code, and a class that
        // says `RxError` must not be matched by a bare `TypeError` path.
        if let Some(code) = &case.error_code {
            assert_eq!(
                code, "CI1",
                "{}: unexpected upstream error code {code} for class {}",
                case.schema, case.class
            );
            assert!(
                case.class.contains("missing-indexed-field"),
                "{}: error code CI1 belongs to the missing-field class, not {}",
                case.schema,
                case.class
            );
        }

        // `upstream-requires-numeric-index-bounds` is the loosest of the three,
        // because upstream can fail an unindexable numeric field two ways and both
        // are the same rule from the caller's side: `getStringLengthOfIndexNumber`
        // throws "Cannot read properties of undefined (reading 'minimum')" when the
        // field has no bounds, and `noStringIndex`'s own `passportId` is declared
        // `type: "object"`, which has no index encoding at all. Either refusal is
        // correct; silently producing a string is not.
        let message = encoded.expect_err("checked above").to_string();
        match case.class.as_str() {
            "upstream-requires-numeric-index-bounds" => assert!(
                message.contains("minimum and maximum")
                    || message.contains("unsupported type"),
                "{}: expected a bounds or type error, got {message}",
                case.schema
            ),
            "upstream-rejects-missing-indexed-field" => assert!(
                message.contains("not in properties"),
                "{}: expected a missing-field error, got {message}",
                case.schema
            ),
            other => panic!("unexpected class {other}"),
        }
    }
}

/// The vectors must keep covering the clamping boundary, or a green run says
/// nothing about the rule most likely to be wrong.
#[test]
fn the_corpus_still_probes_the_clamping_boundary() {
    let (vectors, _schemas) = load();
    let bounds = vectors
        .cases
        .iter()
        .filter(|case| case.kind == "bounds")
        .count();
    let index_strings = vectors
        .cases
        .iter()
        .filter(|case| case.kind == "index-string")
        .count();
    assert!(
        bounds > 300,
        "bound probes are the clamping oracle; found only {bounds}"
    );
    assert!(
        index_strings > 300,
        "index-string cases are the encoding oracle; found only {index_strings}"
    );
    assert_eq!(vectors.case_count, vectors.cases.len());
}

/// Sanity: the sentinel the bounds code uses is upstream's `INDEX_MAX`, a single
/// U+FFFF, and not something stringified.
#[test]
fn the_index_max_sentinel_is_one_code_unit() {
    assert_eq!(index_max_str().chars().count(), 1);
    assert_eq!(index_max_str(), "\u{FFFF}");
}
